-- Contextualize existing module registers without dropping legacy fields or records.
-- Apply after 0052_restore_existing_account_access.sql and verify on staging first.
BEGIN;
DO $$ BEGIN
 IF (SELECT count(*) FROM public.intranet_modules WHERE page_id = ANY(ARRAY['rse.recycling','rse.packaging','rse.co2','rse.esg','rse.points','marketing.content','marketing.podcasts','marketing.analytics','security.vpn','security.environments','product.integrations','support.onboarding','support.compliance','audit.reports']::text[])) <> 14
 THEN RAISE EXCEPTION 'Missing prerequisite intranet modules for specialization'; END IF;
END $$;
UPDATE public.intranet_modules AS m
SET definition = m.definition || jsonb_build_object(
 'fields', specification.fields,
 'description', specification.description,
 'operationalNote', specification.operational_note,
 'recordLabel', specification.record_label
)
FROM (VALUES
  ('rse.recycling', '[{"key":"period","label":"Période de collecte","type":"text","required":true},{"key":"category","label":"Matière et flux","type":"text","required":true},{"key":"quantity","label":"Masse ou volume collecté","type":"number","required":true},{"key":"unit","label":"Unité de mesure","type":"text","required":true},{"key":"method","label":"Méthode de pesée et périmètre","type":"textarea","required":true},{"key":"source","label":"Justificatif ou registre source","type":"text","required":true},{"key":"partner","label":"Collecteur ou partenaire","type":"text","required":false},{"key":"destination","label":"Filière de valorisation","type":"text","required":false},{"key":"receipt_reference","label":"Référence du bordereau","type":"text","required":false},{"key":"measurement_limits","label":"Limites et réserves","type":"textarea","required":false}]'::jsonb, 'Suivi des flux réellement collectés, pesés et orientés vers une filière de traitement.', 'Registre de mesures documentées : aucune collecte physique ni émission de certificat n''est déclenchée automatiquement.', 'mesure de recyclage'),
  ('rse.packaging', '[{"key":"period","label":"Période de contrôle","type":"text","required":true},{"key":"category","label":"Famille d''emballages","type":"text","required":true},{"key":"quantity","label":"Quantité contrôlée","type":"number","required":true},{"key":"unit","label":"Unité contrôlée","type":"text","required":true},{"key":"method","label":"Critères de contrôle et échantillonnage","type":"textarea","required":true},{"key":"source","label":"Fiche technique ou preuve fournisseur","type":"text","required":true},{"key":"material","label":"Composition et matériau","type":"text","required":false},{"key":"supplier_reference","label":"Fournisseur et référence","type":"text","required":false},{"key":"certification","label":"Norme ou certification vérifiée","type":"text","required":false},{"key":"decision_scope","label":"Limites de l''avis qualité","type":"textarea","required":false}]'::jsonb, 'Qualification des matériaux, emballages et preuves de conformité avant leur usage.', 'La validation d''une fiche n''homologue pas automatiquement l''emballage sur Platform et ne commande aucun stock.', 'dossier emballage'),
  ('rse.co2', '[{"key":"period","label":"Période de calcul","type":"text","required":true},{"key":"category","label":"Poste ou activité émettrice","type":"text","required":true},{"key":"quantity","label":"Valeur calculée","type":"number","required":true},{"key":"unit","label":"Unité (kgCO₂e, tCO₂e…)","type":"text","required":true},{"key":"method","label":"Méthode, périmètre et facteurs d''émission","type":"textarea","required":true},{"key":"source","label":"Origine du facteur d''émission","type":"text","required":true},{"key":"scope","label":"Périmètre d''émission","type":"text","required":false},{"key":"baseline","label":"Scénario de référence","type":"text","required":false},{"key":"assumptions","label":"Hypothèses et exclusions","type":"textarea","required":false},{"key":"uncertainty","label":"Incertitudes du calcul","type":"textarea","required":false}]'::jsonb, 'Traçabilité des estimations d''émissions et des hypothèses de calcul.', 'Les valeurs sont déclarées avec leur méthode et leur source. Ce registre n''est pas une mesure automatique des émissions de Platform.', 'calcul d''impact'),
  ('rse.esg', '[{"key":"period","label":"Exercice et période couverte","type":"text","required":true},{"key":"category","label":"Indicateur ESG","type":"text","required":true},{"key":"quantity","label":"Valeur rapportée","type":"number","required":true},{"key":"unit","label":"Unité et base de mesure","type":"text","required":true},{"key":"method","label":"Méthodologie de calcul","type":"textarea","required":true},{"key":"source","label":"Source primaire et traçabilité","type":"text","required":true},{"key":"framework","label":"Référentiel de publication","type":"text","required":false},{"key":"coverage","label":"Entités ou opérations couvertes","type":"text","required":false},{"key":"data_quality","label":"Fiabilité et limites","type":"textarea","required":false},{"key":"external_audit","label":"Référence de revue externe","type":"text","required":false}]'::jsonb, 'Constitution et validation des indicateurs de reporting extra-financier.', 'Les indicateurs ne deviennent pas des déclarations publiées ou auditées par leur simple validation interne.', 'indicateur ESG'),
  ('rse.points', '[{"key":"period","label":"Période de simulation","type":"text","required":true},{"key":"category","label":"Action envisagée","type":"text","required":true},{"key":"quantity","label":"Volume simulé (non crédité)","type":"number","required":true},{"key":"unit","label":"Unité de simulation","type":"text","required":true},{"key":"method","label":"Règles de simulation et d''éligibilité","type":"textarea","required":true},{"key":"source","label":"Source des hypothèses","type":"text","required":true},{"key":"pilot_stage","label":"Stade du pilote","type":"text","required":false},{"key":"reward_policy","label":"Règles de récompense envisagées","type":"textarea","required":false},{"key":"fraud_controls","label":"Prévention des abus","type":"textarea","required":false},{"key":"platform_dependency","label":"Condition d''activation Platform","type":"textarea","required":false}]'::jsonb, 'Conception et contrôle du futur programme de points circulaires.', 'Programme non activé : aucune ligne de ce registre n''attribue des points à un client ou ne crédite un solde dans Platform.', 'hypothèse de fidélité'),
  ('marketing.content', '[{"key":"channel","label":"Canal de destination","type":"text","required":true},{"key":"audience","label":"Public visé","type":"text","required":true},{"key":"content","label":"Texte, scénario ou brief","type":"textarea","required":true},{"key":"publication_date","label":"Date de publication prévue","type":"date","required":false},{"key":"budget","label":"Budget prévu","type":"number","required":false},{"key":"result","label":"Résultat observé","type":"number","required":false},{"key":"source","label":"Source de la mesure","type":"text","required":false},{"key":"format","label":"Format et déclinaisons","type":"text","required":false},{"key":"call_to_action","label":"Appel à l''action","type":"text","required":false},{"key":"rights_reference","label":"Droits et autorisations des médias","type":"text","required":false},{"key":"published_url","label":"Adresse de publication vérifiée","type":"text","required":false}]'::jsonb, 'Production, revue et calendrier des contenus de communication.', 'Un contenu validé reste interne tant qu''un outil de publication ne confirme pas explicitement sa mise en ligne.', 'contenu éditorial'),
  ('marketing.podcasts', '[{"key":"channel","label":"Plateforme de diffusion envisagée","type":"text","required":true},{"key":"audience","label":"Audience ciblée","type":"text","required":true},{"key":"content","label":"Synopsis, conducteur et intervenants","type":"textarea","required":true},{"key":"publication_date","label":"Date prévue de diffusion","type":"date","required":false},{"key":"budget","label":"Budget de production","type":"number","required":false},{"key":"result","label":"Écoutes confirmées","type":"number","required":false},{"key":"source","label":"Source des statistiques d''écoute","type":"text","required":false},{"key":"episode_number","label":"Numéro d''épisode","type":"text","required":false},{"key":"guest_consent","label":"Consentement et droits voix/image","type":"text","required":false},{"key":"audio_master","label":"Référence du fichier master","type":"text","required":false},{"key":"published_url","label":"Lien de diffusion confirmé","type":"text","required":false}]'::jsonb, 'Préparation, validation éditoriale et suivi des épisodes audio.', 'La validation du dossier n''enregistre, n''héberge et ne publie aucun épisode automatiquement.', 'épisode podcast'),
  ('marketing.analytics', '[{"key":"indicator","label":"Indicateur et définition","type":"text","required":true},{"key":"period","label":"Période observée","type":"text","required":true},{"key":"channel","label":"Canal ou campagne","type":"text","required":true},{"key":"value","label":"Valeur relevée","type":"number","required":true},{"key":"unit","label":"Unité de mesure","type":"text","required":true},{"key":"source","label":"Source et date d''extraction","type":"text","required":true},{"key":"analysis","label":"Interprétation et limites","type":"textarea","required":false},{"key":"campaign_reference","label":"Référence campagne","type":"text","required":false},{"key":"attribution_window","label":"Fenêtre d''attribution","type":"text","required":false},{"key":"comparison_period","label":"Période de comparaison","type":"text","required":false},{"key":"action_recommended","label":"Action proposée","type":"textarea","required":false}]'::jsonb, 'Mesures documentées de performance des canaux et campagnes.', 'Les chiffres sont des saisies documentées. Ils ne constituent pas une synchronisation automatique avec les régies publicitaires.', 'mesure marketing'),
  ('security.vpn', '[{"key":"asset","label":"Ressource réseau demandée","type":"text","required":true},{"key":"environment","label":"Environnement concerné","type":"text","required":true},{"key":"finding","label":"Justification de l''accès","type":"textarea","required":true},{"key":"action","label":"Action et approbation requises","type":"textarea","required":true},{"key":"verification","label":"Preuve d''autorisation et de révocation","type":"textarea","required":false},{"key":"review_date","label":"Date de réexamen","type":"date","required":false},{"key":"beneficiary","label":"Bénéficiaire identifié","type":"text","required":false},{"key":"access_duration","label":"Durée d''accès demandée","type":"text","required":false},{"key":"ticket_reference","label":"Référence de demande IT","type":"text","required":false},{"key":"revocation_evidence","label":"Preuve de révocation","type":"text","required":false}]'::jsonb, 'Demandes et revues d''accès aux réseaux sécurisés.', 'Ce module documente les demandes et les contrôles. La validation n''ouvre aucun VPN ni ne provisionne un compte réseau.', 'revue d''accès VPN'),
  ('security.environments', '[{"key":"asset","label":"Application ou composant","type":"text","required":true},{"key":"environment","label":"Environnement cible","type":"text","required":true},{"key":"finding","label":"Changement ou risque constaté","type":"textarea","required":true},{"key":"action","label":"Plan d''intervention","type":"textarea","required":true},{"key":"verification","label":"Preuves de tests et contrôle","type":"textarea","required":false},{"key":"review_date","label":"Date de revue","type":"date","required":false},{"key":"release_reference","label":"Version ou commit ciblé","type":"text","required":false},{"key":"deployment_window","label":"Fenêtre d''intervention","type":"text","required":false},{"key":"rollback_plan","label":"Plan de retour arrière","type":"textarea","required":false},{"key":"execution_trace","label":"Lien vers le journal d''exécution","type":"text","required":false}]'::jsonb, 'Contrôles des environnements, changements et plans de retour arrière.', 'La validation d''un dossier n''exécute ni déploiement, ni rollback. L''action technique doit être tracée par le système de déploiement.', 'revue d''environnement'),
  ('product.integrations', '[{"key":"area","label":"Système ou parcours concerné","type":"text","required":true},{"key":"problem","label":"Besoin et événement déclencheur","type":"textarea","required":true},{"key":"acceptance","label":"Contrats et critères d''acceptation","type":"textarea","required":true},{"key":"version","label":"Version d''API ou de schéma","type":"text","required":false},{"key":"dependency","label":"Service et dépendances","type":"text","required":false},{"key":"result","label":"Résultat de recette vérifiable","type":"textarea","required":false},{"key":"source_system","label":"Système émetteur","type":"text","required":false},{"key":"target_system","label":"Système destinataire","type":"text","required":false},{"key":"idempotency_key","label":"Stratégie d''idempotence","type":"text","required":false},{"key":"retry_policy","label":"Échec, reprise et alerte","type":"textarea","required":false}]'::jsonb, 'Contrats d''API, dépendances, qualité des échanges et tests des intégrations.', 'Une fiche approuvée n''active aucune intégration. Les changements du bridge Platform/Intranet exigent leurs propres tests et validations.', 'intégration technique'),
  ('support.onboarding', '[{"key":"account","label":"Compte ou organisation accompagnée","type":"text","required":true},{"key":"category","label":"Parcours partenaire","type":"text","required":false},{"key":"issue","label":"Étape bloquante","type":"textarea","required":true},{"key":"resolution","label":"Plan de résolution","type":"textarea","required":false},{"key":"sla_date","label":"Échéance de prise en charge","type":"date","required":false},{"key":"platform_reference","label":"Identifiant Platform","type":"text","required":false},{"key":"next_step","label":"Prochaine étape","type":"text","required":false},{"key":"contact_channel","label":"Canal de contact","type":"text","required":false},{"key":"completion_evidence","label":"Preuve de finalisation","type":"text","required":false}]'::jsonb, 'Suivi des étapes d''accompagnement et des blocages d''intégration des partenaires.', 'Un dossier Support ne crée ni compte marchand ni fournisseur ; les identités restent contrôlées par Platform et les procédures RH concernées.', 'suivi d''onboarding'),
  ('support.compliance', '[{"key":"account","label":"Compte concerné","type":"text","required":true},{"key":"category","label":"Type de contrôle","type":"text","required":false},{"key":"issue","label":"Écart ou document manquant","type":"textarea","required":true},{"key":"resolution","label":"Action de régularisation","type":"textarea","required":false},{"key":"sla_date","label":"Date limite de suivi","type":"date","required":false},{"key":"compliance_reference","label":"Référence du dossier Conformité","type":"text","required":false},{"key":"documents_requested","label":"Pièces demandées","type":"textarea","required":false},{"key":"handoff_team","label":"Pôle destinataire","type":"text","required":false},{"key":"customer_update","label":"Information communiquée au client","type":"textarea","required":false}]'::jsonb, 'Suivi Support des pièces et blocages de conformité, avec orientation vers le pôle compétent.', 'Ce suivi ne rend pas de décision juridique ou KYC ; le pôle Conformité reste responsable des contrôles formels.', 'suivi de conformité client'),
  ('audit.reports', '[{"key":"entity","label":"Entité auditée","type":"text","required":true},{"key":"reference","label":"Référence de mission","type":"text","required":false},{"key":"finding","label":"Synthèse des constats","type":"textarea","required":true},{"key":"evidence","label":"Éléments probants","type":"textarea","required":false},{"key":"corrective_action","label":"Recommandations","type":"textarea","required":true},{"key":"review_date","label":"Date de validation envisagée","type":"date","required":false},{"key":"auditor","label":"Auditeur principal","type":"text","required":false},{"key":"audit_scope","label":"Périmètre de mission","type":"textarea","required":false},{"key":"opinion","label":"Conclusion et réserves","type":"textarea","required":false},{"key":"corrective_plan_ref","label":"Référence du plan correctif","type":"text","required":false}]'::jsonb, 'Constitution de rapports d''audit et traçabilité des constats et preuves.', 'Un rapport validé ne clôt pas automatiquement les non-conformités ni les actions correctives ; ces objets conservent leur cycle de vie.', 'rapport d''audit')
) AS specification(id, fields, description, operational_note, record_label)
WHERE m.page_id = specification.id;
COMMIT;
